import { useState } from 'react';
import { LuCopy, LuPlay, LuChevronDown, LuChevronRight, LuFileInput } from 'react-icons/lu';
import { useConsultaEnChat, ResultadoEnChat } from './ResultadoEnChat.jsx';

/**
 * SqlBlock — Collapsible SQL code block with copy, run, and syntax highlighting.
 * Used inside chat messages to display queries generated by the AI agent.
 *
 * `onInsert` puts the query in the active editor at the cursor, or over the
 * selected text (plan del Assistant, A2). It used to offer «Replace file content»
 * and «Append to file»: the first wiped everything else in the file with no
 * warning, and both cut the editor's undo history.
 *
 * `enChat` (E6/A7): «Run» runs the query here and shows the result below it;
 * `onRun` becomes «Open in editor». Without it (Deep Dive), «Run» opens a tab.
 *
 * Linear UI redesign: all styles in index.css under ai-sql-* classes.
 */
const SqlBlock = ({ sql, onRun, onInsert, defaultExpanded = true, enChat = false }) => {
    const [isExpanded, setIsExpanded] = useState(defaultExpanded);
    const consulta = useConsultaEnChat();
    const [copied, setCopied] = useState(false);

    const handleCopy = () => {
        navigator.clipboard.writeText(sql);
        setCopied(true);
        setTimeout(() => setCopied(false), 1500);
    };

    const headerClasses = [
        'ai-sql-header',
        isExpanded ? 'ai-sql-header--expanded' : '',
    ].filter(Boolean).join(' ');

    const copyBtnClasses = [
        'ai-sql-btn',
        copied ? 'ai-sql-btn--copied' : '',
    ].filter(Boolean).join(' ');

    return (
        <div className="ai-sql">
            {/* Header */}
            <div
                className={headerClasses}
                onClick={() => setIsExpanded(!isExpanded)}
            >
                <div className="ai-sql-label">
                    {isExpanded ? <LuChevronDown size={12} /> : <LuChevronRight size={12} />}
                    SQL Query
                </div>
                <div className="ai-sql-actions" onClick={e => e.stopPropagation()}>
                    <button
                        className={copyBtnClasses}
                        onClick={handleCopy}
                        title="Copy SQL"
                    >
                        <LuCopy size={11} /> {copied ? 'Copied!' : 'Copy'}
                    </button>

                    {onInsert && (
                        <button
                            className="ai-sql-btn"
                            onClick={() => onInsert(sql)}
                            title="Insert at the cursor, or replace the selected text (Ctrl+Z undoes it)"
                        >
                            <LuFileInput size={11} /> Insert
                        </button>
                    )}

                    {(onRun || enChat) && (
                        <button
                            className="ai-sql-btn ai-sql-btn--accent"
                            onClick={() => (enChat ? consulta.correr(sql) : onRun(sql))}
                            title={enChat ? 'Run it here, in the chat' : 'Run in editor'}
                        >
                            <LuPlay size={11} /> Run
                        </button>
                    )}
                </div>
            </div>

            {/* Code */}
            {isExpanded && (
                <pre className="ai-sql-code">
                    {sql}
                </pre>
            )}
            {enChat && (
                <ResultadoEnChat estado={consulta.estado} onCerrar={consulta.cerrar} onAbrirEnEditor={onRun ? () => onRun(sql) : null} />
            )}
        </div>
    );
};

export default SqlBlock;
